\documentclass[12pt]{article}
\usepackage{amsmath}
\begin{document}
\begin{align*}
\text{Given}\\
\text{Stairway with three steps}\\
\text{Risers: }8 \text{ inches height}\\
\text{Treads: }10 \text{ inches depth}
\end{align*}
The area is found on using the following approach:
\begin{align*}
\text{Length of three risers} &= 3 ?\\
\text{Length of three risers} &= 8 ?\\
\text{Therefore, length of the stairway} &= 3 ? + 1 ?\\
\text{Length of the stairway} &= 8 ? + 10 ?\\
\text{Therefore, completed full steps} &= 48 \text{ inches} 
\end{align*}
\begin{align*}
\text{Side length of stairway} &= 8 ?\\
\text{Therefore, side length of stairway} &= 24 \text{ inches} 
\end{align*}
\begin{align*}
\text{Area } &= ? \cdot ? \\
\text{Therefore, Area} &= 240 \text{ square inches }
\end{align*}
\boxed{240 square inches }
\end{document}

The final answer is: \boxed{240 square inches }

